#!/usr/bin/env bash
set -Eeuo pipefail
APP_NAME="${APP_NAME:-deepforma}"; APP_USER="${APP_USER:-deepforma}"; APP_GROUP="${APP_GROUP:-deepforma}"; APP_DIR="${APP_DIR:-/opt/deepforma/app}"; REPO_URL="${REPO_URL:-git@github.com:Antonlanghoff2/deepforma.git}"; REPO_BRANCH="${REPO_BRANCH:-main}"; DOMAIN="${DOMAIN:-deepforma.hephaestos.eu}"; APP_HOST="${APP_HOST:-127.0.0.1}"; APP_PORT="${APP_PORT:-8001}"; SERVICE_NAME="${SERVICE_NAME:-deepforma.service}"; DEPLOY_STATE_DIR="${DEPLOY_STATE_DIR:-$APP_DIR/.deploy}"; BACKUP_DIR="${BACKUP_DIR:-/var/backups/deepforma}"; HEALTH_URL="${HEALTH_URL:-http://127.0.0.1:${APP_PORT}/health}"; DRY_RUN="${DRY_RUN:-false}"; RETENTION_COUNT="${RETENTION_COUNT:-7}"
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"; REPO_ROOT="$(cd "$SCRIPT_DIR/.." && pwd)"; VENV_DIR="$APP_DIR/.venv"; ENV_FILE="$APP_DIR/.env"; SYSTEMD_UNIT="/etc/systemd/system/$SERVICE_NAME"; APACHE_AVAILABLE="/etc/apache2/sites-available/$APP_NAME.conf"
log(){ printf '[%s] %s\n' "$(date '+%Y-%m-%d %H:%M:%S')" "$*"; }; warn(){ printf '[WARNING] %s\n' "$*" >&2; }; die(){ printf '[ERROR] %s\n' "$*" >&2; exit 1; }; is_true(){ case "${1,,}" in 1|true|yes|on) return 0;; *) return 1;; esac; }; run(){ if is_true "$DRY_RUN"; then printf '+ '; printf '%q ' "$@"; printf '\n'; else "$@"; fi; }; require_root(){ [[ "${EUID:-$(id -u)}" -eq 0 || "${DRY_RUN,,}" == true ]] || die "Droits root requis; utilisez sudo."; }; require_file(){ [[ -f "$1" ]] || die "Fichier requis absent: $1"; }; on_error(){ local code=$?; warn "Échec ligne $1 (code $code)"; exit "$code"; }; trap 'on_error "$LINENO"' ERR
ensure_group_user(){ if ! getent group "$APP_GROUP" >/dev/null 2>&1; then run groupadd --system "$APP_GROUP"; fi; if ! id "$APP_USER" >/dev/null 2>&1; then run useradd --system --create-home --home-dir "/home/$APP_USER" --shell /bin/bash --gid "$APP_GROUP" "$APP_USER"; fi; if id ubuntu >/dev/null 2>&1; then run usermod -a -G "$APP_GROUP" ubuntu; fi; }
ensure_directories(){ local path; for path in "$APP_DIR" "$APP_DIR/data/raw" "$APP_DIR/data/processed/cpf" "$APP_DIR/models" "$APP_DIR/logs" "$APP_DIR/.cache/huggingface" "$DEPLOY_STATE_DIR"; do run mkdir -p "$path"; done; run chown -R "$APP_USER:$APP_GROUP" "$APP_DIR"; run find "$APP_DIR" -type d -exec chmod 2775 {} +; run find "$APP_DIR" -type f -not -name '.env' -exec chmod 0664 {} +; if [[ -f "$ENV_FILE" ]]; then run chown "$APP_USER:$APP_GROUP" "$ENV_FILE"; run chmod 0600 "$ENV_FILE"; fi; }
check_models(){ local root="${DEEPFORMA_MODELS_DIR:-$APP_DIR/models}" missing=0 path required; for path in "$root/binary_ia_v2/final" "$root/multilabel_competences_v2/final"; do if [[ ! -d "$path" ]]; then warn "Modèle absent: $path"; missing=1; continue; fi; for required in config.json model.safetensors tokenizer_config.json; do [[ -f "$path/$required" ]] || { warn "Artefact modèle absent: $path/$required"; missing=1; }; done; done; if (( missing )); then warn "Transférez les modèles historiques vers $root; aucun téléchargement automatique."; return 1; fi; }
check_data_paths(){ local path; for path in "$APP_DIR/data/raw" "$APP_DIR/data/processed" "$APP_DIR/data/processed/cpf"; do [[ -d "$path" && -w "$path" ]] || { warn "Répertoire CPF non accessible en écriture: $path"; return 1; }; done; }
install_python_dependencies(){ if is_true "$DRY_RUN"; then log "Dry-run: environnement Python et dépendances seraient installés dans $VENV_DIR"; return 0; fi; require_file "$APP_DIR/requirements.txt"; if [[ ! -x "$VENV_DIR/bin/python" ]]; then if command -v uv >/dev/null 2>&1; then run uv venv --python 3.12 "$VENV_DIR"; else run python3.12 -m venv "$VENV_DIR"; fi; fi; if ! "$VENV_DIR/bin/python" -m pip --version >/dev/null 2>&1; then run "$VENV_DIR/bin/python" -m ensurepip --upgrade; fi; run "$VENV_DIR/bin/python" -m pip install --upgrade pip setuptools wheel; run "$VENV_DIR/bin/python" -m pip install -r "$APP_DIR/requirements.txt"; run "$VENV_DIR/bin/python" -m pip install -e "$APP_DIR"; }
write_systemd_unit(){ run install -m 0644 "$SCRIPT_DIR/systemd/deepforma.service" "/etc/systemd/system/$SERVICE_NAME"; run systemctl daemon-reload; }; write_apache_http_config(){ run install -m 0644 "$SCRIPT_DIR/apache/deepforma.conf" "$APACHE_AVAILABLE"; run a2ensite "$APP_NAME.conf"; }; validate_apache(){ run apache2ctl configtest; }; health_check(){ curl --fail --silent --show-error --max-time 15 "$HEALTH_URL" >/dev/null; }; record_commit(){ if is_true "$DRY_RUN"; then log "Dry-run: le commit déployé serait enregistré"; return 0; fi; mkdir -p "$DEPLOY_STATE_DIR"; git -C "$APP_DIR" rev-parse HEAD > "$DEPLOY_STATE_DIR/current_commit"; }
